INSERT INTO faq (category, question, answer) VALUES
('예약·결제', '예약은 어떻게 하나요?', '[객실 예약]에서 날짜와 인원을 고른 뒤 객실을 선택하고, 결제 화면에서 쿠폰과 결제 방법을 고르면 예약이 완료됩니다.\n로그인한 회원만 예약할 수 있습니다.'),
('예약·결제', '예약을 취소하고 싶어요.', '체크인 날짜 전까지는 마이페이지 [내 예약 내역]에서 무료로 취소할 수 있습니다.\n체크인 당일부터는 온라인 취소가 불가능하니 호텔(031-000-0000)로 연락해 주세요.'),
('예약·결제', '어떤 결제 방법이 있나요?', '카드결제, 계좌이체, 현장결제(체크인 시 프런트에서 결제) 중에서 고를 수 있습니다.'),
('예약·결제', '쿠폰은 어떻게 사용하나요?', '결제 화면의 쿠폰 칸에 쿠폰 번호를 넣고 [적용]을 누르면 할인 금액이 바로 계산됩니다. 쿠폰마다 사용 기간이 정해져 있습니다.'),
('예약·결제', '인원이 늘면 요금이 달라지나요?', '객실마다 기준 인원이 있고, 기준 인원을 넘는 1명마다 1박 추가 요금이 붙습니다. 객실 상세 화면에서 예상 금액을 확인할 수 있습니다.'),
('객실', '체크인, 체크아웃 시간은 언제인가요?', '체크인은 오후 3시부터, 체크아웃은 오전 11시까지입니다. 얼리 체크인·늦은 체크인은 결제 화면 요청사항에 남겨 주세요.'),
('객실', '바다가 보이는 객실이 있나요?', '오션뷰 객실에서 서해 바다와 노을을 볼 수 있습니다. 객실 검색의 전망 필터에서 [오션뷰]를 선택해 보세요.'),
('객실', '반려동물과 함께 묵을 수 있나요?', '반려동물 동반 가능 객실에서만 함께 머무를 수 있습니다. 객실 검색의 [반려동물 동반] 필터를 이용해 주세요.'),
('시설·서비스', '주차가 가능한가요?', '투숙객은 지하 주차장을 무료로 이용할 수 있습니다. (1객실 1대)'),
('시설·서비스', '조식은 어디서 먹나요?', '조식 포함 객실은 2층 레스토랑에서 오전 7시 ~ 10시에 조식을 드실 수 있습니다.'),
('시설·서비스', '자전거를 빌릴 수 있나요?', '프런트에서 자전거를 무료로 빌려 배곧한울공원 해안 산책로를 달릴 수 있습니다.'),
('회원', '회원 정보는 어디서 바꾸나요?', '마이페이지 [회원 정보 수정]에서 비밀번호, 이름, 연락처, 이메일을 바꿀 수 있습니다.'),
('회원', '회원 탈퇴는 어떻게 하나요?', '[회원 정보 수정] 화면 아래 [회원 탈퇴]에서 할 수 있습니다. 이용 예정인 예약이 있으면 먼저 취소해야 합니다.');
